#include "expression_matrix_writer.hpp"
#ifdef QUPATHXX_HAS_PROJECT
#include <fstream>
#include <random>
#include <chrono>
namespace qpx::detail::matrix {
namespace {
namespace fs=std::filesystem;
struct Stage {
    fs::path directory,file;
    explicit Stage(const fs::path& parent){std::random_device random;constexpr char hex[]="0123456789abcdef";for(int i=0;i<16;++i){std::string name=".qpx-expression-";for(int j=0;j<32;++j)name+=hex[random()&15];auto candidate=parent/fs::u8path(name);std::error_code error;if(fs::create_directory(candidate,error)){directory=std::move(candidate);file=directory/"matrix.sqlite";return;}if(error && error!=std::errc::file_exists)throw fs::filesystem_error("Cannot create expression staging directory",candidate,error);}throw std::runtime_error("Cannot allocate expression staging directory");}
    ~Stage(){std::error_code error;for(const char* suffix:{"","-journal","-wal","-shm"}){auto path=file;path+=suffix;fs::remove(path,error);}fs::remove(directory,error);}
};
void gene_hashes(Database& db,const ExpressionMatrixMetadata& m,const std::atomic<bool>* c){Statement features(db,"SELECT idx,id,name,type,sha256 FROM features ORDER BY idx"),counts(db,"SELECT observation,value FROM counts WHERE feature=? ORDER BY observation"),update(db,"UPDATE features SET sha256=? WHERE idx=?");std::uint64_t entries=0,expected=0;while(features.step()){workflow_checkpoint(c);const auto f=feature(features,false);if(f.index!=expected++)throw std::invalid_argument("Expression feature axis is not contiguous");GeneHash hash(f,m.input_sha256[2]);counts.number(1,f.index);while(counts.step()){if((entries&4095)==0){workflow_checkpoint(c);db.admit(0);}const auto value=counts.value(1);if(m.domain==ExpressionValueDomain::Continuous)(void)real_value(value);hash.add(counts.number(0),value);++entries;}counts.reset();update.text(1,hash.finish());update.number(2,f.index);update.step();update.reset();}if(expected!=m.features || entries!=m.entries)throw std::runtime_error("Expression index entry/feature count differs");}
std::string destination(const std::string& store){const auto path=export_path(store);if(fs::exists(fs::u8path(path)))throw WorkflowOutputExists("Expression sidecar output already exists");return path;}
}
struct Writer::Data {
    std::string path;ExpressionMatrixMetadata metadata;ExpressionMatrixImportOptions limits;std::size_t reserved;const std::atomic<bool>* cancelled;
    std::chrono::steady_clock::time_point began=std::chrono::steady_clock::now();Stage stage;
    std::unique_ptr<Database> db;std::unique_ptr<Statement> features,observations,counts,coordinates;
    std::uint64_t feature_count=0,observation_count=0,entry_count=0;std::string frame_sha;Sha256 coordinate_digest;bool finished=false;
    Data(const std::string& store,ExpressionMatrixMetadata m,ExpressionMatrixImportOptions p,std::size_t external,const std::atomic<bool>* c):path(destination(store)),metadata(std::move(m)),limits(p),reserved(external),cancelled(c),stage(fs::u8path(path).parent_path()){
        limits.validate();workflow_checkpoint(c);if(!metadata.features || metadata.features>limits.max_features || !metadata.observations || metadata.observations>limits.max_observations || metadata.entries>limits.max_entries)throw WorkflowCaptureLimit("Expression dimensions/entries exceed import limits");
        if(reserved>limits.work_bytes || limits.work_bytes-reserved<4u*1024*1024)throw WorkflowCaptureLimit("Expression decoder leaves no indexed writer budget");
        db=std::make_unique<Database>(stage.file.u8string(),true,limits.work_bytes-reserved,c);
        db->exec("PRAGMA page_size=4096; PRAGMA max_page_count="+std::to_string(limits.store_bytes/4096)+"; PRAGMA journal_mode=OFF; PRAGMA synchronous=OFF;");
        db->exec("CREATE TABLE metadata(key TEXT PRIMARY KEY NOT NULL,value TEXT NOT NULL) STRICT, WITHOUT ROWID; CREATE TABLE features(idx INTEGER PRIMARY KEY,id TEXT UNIQUE NOT NULL,name TEXT NOT NULL,type TEXT NOT NULL,sha256 TEXT NOT NULL) STRICT; CREATE TABLE observations(idx INTEGER PRIMARY KEY,id TEXT UNIQUE NOT NULL) STRICT; CREATE TABLE counts(feature INTEGER NOT NULL,observation INTEGER NOT NULL,value BLOB NOT NULL CHECK(length(value)=8),PRIMARY KEY(feature,observation)) STRICT, WITHOUT ROWID; PRAGMA application_id=1364219973; PRAGMA user_version=1; BEGIN;");
        if(!legacy(metadata)){if(!metadata.spatial_frame || metadata.input_matrix.empty() || metadata.input_spatial.empty())throw std::invalid_argument("H5AD import needs coordinates/frame and explicit dataset keys");frame_sha=metadata.spatial_frame->sha256();db->exec("PRAGMA user_version=3; CREATE TABLE coordinates(observation INTEGER PRIMARY KEY NOT NULL,x BLOB NOT NULL CHECK(length(x)=8),y BLOB NOT NULL CHECK(length(y)=8),sha256 TEXT NOT NULL) STRICT;");coordinates=std::make_unique<Statement>(*db,"INSERT INTO coordinates VALUES(?,?,?,?)");text(coordinate_digest,"qpx.expression-coordinates/1");text(coordinate_digest,frame_sha);coordinate_digest.integer(metadata.observations);}
        features=std::make_unique<Statement>(*db,"INSERT INTO features VALUES(?,?,?,?, '')");observations=std::make_unique<Statement>(*db,"INSERT INTO observations VALUES(?,?)");counts=std::make_unique<Statement>(*db,"INSERT INTO counts VALUES(?,?,?)");
    }
    void value(std::uint64_t feature,std::uint64_t observation,std::uint64_t bits){workflow_checkpoint(cancelled);if(finished || feature>=metadata.features || observation>=metadata.observations || entry_count>=metadata.entries)throw std::invalid_argument("Expression entry outside declared axes/entries");const auto bytes=encoded(bits);counts->number(1,feature);counts->number(2,observation);counts->value(3,bytes);counts->step();counts->reset();if((entry_count++&4095)==0)db->admit(0);}
};
Writer::Writer(const std::string& s,ExpressionMatrixMetadata m,ExpressionMatrixImportOptions p,std::size_t r,const std::atomic<bool>* c):data_(std::make_unique<Data>(s,std::move(m),p,r,c)){}
Writer::~Writer()=default;
void Writer::feature_row(std::uint64_t i,const std::string& id,const std::string& name,const std::string& type){auto& d=*data_;workflow_checkpoint(d.cancelled);if(d.finished || i!=d.feature_count || i>=d.metadata.features)throw std::invalid_argument("Expression feature axis not contiguous");spatial_identifier(id);spatial_identifier(name);spatial_identifier(type);d.features->number(1,i);d.features->text(2,id);d.features->text(3,name);d.features->text(4,type);d.features->step();d.features->reset();if((d.feature_count++&4095)==0)d.db->admit(0);}
void Writer::observation_row(std::uint64_t i,const std::string& id,std::optional<Point> point){auto& d=*data_;workflow_checkpoint(d.cancelled);if(d.finished || i!=d.observation_count || i>=d.metadata.observations || bool(point)!=bool(d.coordinates))throw std::invalid_argument("Expression observation/coordinate axis differs");spatial_identifier(id);d.observations->number(1,i);d.observations->text(2,id);d.observations->step();d.observations->reset();if(point){const auto x=encoded(real_bits(point->x)),y=encoded(real_bits(point->y));const auto digest=coordinate_hash(i,id,*point,d.frame_sha);d.coordinates->number(1,i);d.coordinates->value(2,x);d.coordinates->value(3,y);d.coordinates->text(4,digest);d.coordinates->step();d.coordinates->reset();text(d.coordinate_digest,digest);}if((d.observation_count++&4095)==0)d.db->admit(0);}
void Writer::count(std::uint64_t f,std::uint64_t o,std::uint64_t v){if(data_->metadata.domain!=ExpressionValueDomain::Counts)throw std::invalid_argument("Count insert into continuous source");data_->value(f,o,v);}
void Writer::continuous(std::uint64_t f,std::uint64_t o,double v){if(data_->metadata.domain!=ExpressionValueDomain::Continuous)throw std::invalid_argument("Continuous insert into count source");data_->value(f,o,real_bits(v));}
ExpressionMatrixImportResult Writer::finish(std::array<std::string,3> hashes,std::uint64_t input_bytes,const std::function<void()>& verify){
    auto& d=*data_;workflow_checkpoint(d.cancelled);if(d.finished || d.feature_count!=d.metadata.features || d.observation_count!=d.metadata.observations || d.entry_count!=d.metadata.entries)throw std::invalid_argument("Expression staged axes/entry count incomplete");for(const auto& h:hashes)digest(h);verify();auto& m=d.metadata;m.input_sha256=std::move(hashes);if(d.coordinates)m.spatial_sha256=d.coordinate_digest.finish();m.source_sha256=source_hash(m);
    d.features.reset();d.observations.reset();d.counts.reset();d.coordinates.reset();gene_hashes(*d.db,m,d.cancelled);store_meta(*d.db,m);d.db->exec("COMMIT;");d.db->admit(0);ExpressionMatrixImportResult result;result.peak_work_bytes=d.reserved+d.db->peak();d.db.reset();verify();
    result.file_bytes=fs::file_size(d.stage.file);if(result.file_bytes>d.limits.store_bytes)throw WorkflowCaptureLimit("Expression sidecar exceeds store byte limit");std::ifstream input(d.stage.file,std::ios::binary);if(!input)throw std::runtime_error("Cannot read completed expression sidecar");AtomicExportFile output(d.path,std::size_t(d.limits.store_bytes),d.cancelled);std::array<char,65536> bytes;Sha256 hash;
    while(input){workflow_checkpoint(d.cancelled);input.read(bytes.data(),bytes.size());const auto n=std::size_t(input.gcount());output.write(bytes.data(),n);hash.update(bytes.data(),n);}if(!input.eof() || input.bad() || output.bytes()!=result.file_bytes)throw std::runtime_error("Expression staged copy differs");verify();workflow_checkpoint(d.cancelled);output.commit(false);d.finished=true;result.path=d.path;result.file_sha256=hash.finish();bind_file_identity(m,result.file_sha256);result.metadata=m;result.matrix_bytes=input_bytes;result.elapsed_ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-d.began).count();return result;
}
}
#endif
